mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM T_MBR_INFO_M
    WHERE email = #{email}
)

SELECT EXISTS (
    SELECT 1
    FROM T_MBR_INFO_M
    WHERE phone_number = #{phoneNumber}
)

mapper.insert:
INSERT INTO T_MBR_INFO_M ( role, name, birth_date, phone_number, email, password, profile_image_key
, teeny_score
) VALUES ( #{role}, #{name}, #{birthDate}, #{phoneNumber}, #{email}, #{password}, #{profileImageKey}
, NULL
)

mapper.select:
SELECT id
FROM T_MBR_AGRMT_M
WHERE code = #{code}
  AND version = #{version}
  AND effective_at <= #{now}
  AND (expired_at IS NULL OR expired_at > #{now})

SELECT EXISTS (
SELECT 1
FROM T_MBR_CONN_R
WHERE child_id = #{childId}
AND status = 'ACTIVE'
)
